import{_ as n,o as e,c as i,a2 as r}from"./chunks/framework.CCtxZRER.js";const p=JSON.parse('{"title":"SOP Pengeluaran Barang","description":"Langkah melayani permintaan barang dari divisi lain lewat ERP sampai barang diambil.","frontmatter":{"title":"SOP Pengeluaran Barang","description":"Langkah melayani permintaan barang dari divisi lain lewat ERP sampai barang diambil.","status":"ditinjau","dasar":"alur barang keluar Gudang Teknik","nomor_dokumen":null,"versi":0.2,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik","catatan-alur"],"kata_kunci":["SOP","pengeluaran barang","barang keluar","permintaan","ERP","persetujuan","laporan barang keluar","rak reservasi","catatan manual","FIFO","tukar barang"]},"headers":[],"relativePath":"sop/pengeluaran-barang.md","filePath":"sop/pengeluaran-barang.md"}'),l={name:"sop/pengeluaran-barang.md"};function t(s,a,u,g,d,k){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="sop-pengeluaran-barang" tabindex="-1">SOP Pengeluaran Barang <a class="header-anchor" href="#sop-pengeluaran-barang" aria-label="Permalink to &quot;SOP Pengeluaran Barang&quot;">​</a></h1><p class="lead">Dipakai setiap kali ada permintaan barang dari divisi lain melalui ERP.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Memastikan divisi pemesan menerima barang yang benar, dalam jumlah dan kondisi yang tepat, dan setiap pengeluaran tercatat di ERP dan di rak.</p><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Akses ke ERP Warehouse Teknik.</li><li>Data lokasi barang di database.</li><li>APD sesuai arahan pembimbing.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Buka notifikasi permintaan</strong> di ERP Warehouse Teknik.</li><li><strong>Setujui permintaan</strong> dan buat laporan barang keluar. Laporan ini langsung tercatat di ERP.</li><li><strong>Cari barang</strong> sesuai orderan. Cocokkan kode dan spesifikasinya.</li><li><strong>Ambil barang</strong> dari rak. Dahulukan barang yang masuk lebih dulu (FIFO).</li><li><strong>Isi catatan manual di rak</strong> untuk barang yang diambil.</li><li><strong>Taruh barang di rak reservasi</strong> sampai diambil.</li><li><strong>Serahkan barang</strong> saat karyawan divisi pemesan datang.</li><li><strong>Minta karyawan mengecek barang.</strong> Kalau tidak sesuai orderan, terima kembali barangnya dan tukar dengan yang sesuai.</li></ol><p>Flowchart-nya ada di <a href="/WareHouse/alur-kerja/barang-keluar">Alur Barang Keluar</a>.</p><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Permintaan sudah disetujui di ERP dan laporan barang keluar tercatat.</li><li>Kode dan spesifikasi barang sesuai orderan.</li><li>Catatan manual di rak sudah diisi.</li><li>Barang sudah dicek karyawan dan dinyatakan sesuai.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat mengambil barang</p><ul><li>Pakai tangga atau alat bantu untuk rak tinggi. Jangan memanjat rak.</li><li>Angkat barang dengan menekuk lutut dan punggung tetap lurus. Minta bantuan untuk barang berat atau panjang.</li><li>Pakai sarung tangan untuk barang bersudut tajam.</li></ul></div>',13)])])}const b=n(l,[["render",t]]);export{p as __pageData,b as default};
